 "content": "def transform(grid):
    # Copy the 8-pattern perpendicular to the line joining the two 4 markers.
    h, w = len(grid), len(grid[0])
    pts8 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    pts4 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if len(pts4) < 2 or not pts8:
        return grid
    (r1, c1), (r2, c2) = pts4[:2]
    dr, dc = r2 - r1, c2 - c1
    offsets = [(-dc, dr), (dc, -dr)]
    def fits(off):
        return all(0 <= r + off[0] < h and 0 <= c + off[1] < w for r, c in pts8)
    valid = [off for off in offsets if fits(off)]
    if not valid:
        # If neither full-grid placement fits, choose the direction with the
        # larger in-bounds overlap; the final result is cropped to its objects.
        def overlap(off):
            return sum(0 <= r + off[0] < h and 0 <= c + off[1] < w for r, c in pts8)
        off = max(offsets, key=overlap)
    else:
        off = valid[0]
    allpts = pts8 + [(r + off[0], c + off[1]) for r, c in pts8]
    minr = min(r for r, c in allpts)
    maxr = max(r for r, c in allpts)
    minc = min(c for r, c in allpts)
    maxc = max(c for r, c in allpts)
    out = [[0 for _ in range(maxc - minc + 1)] for _ in range(maxr - minr + 1)]
    for r, c in allpts:
        if minr <= r <= maxr and minc <= c <= maxc:
            out[r - minr][c - minc] = 8
    return out
